BEGIN;
SET LOCAL lock_timeout='15s'; SET LOCAL statement_timeout='120s';
DO $$ BEGIN
 IF to_regclass('public.office_workspaces') IS NULL OR to_regclass('public.office_memberships') IS NULL OR to_regclass('public.office_industry_spaces') IS NULL OR to_regprocedure('office_private.is_active_member(uuid)') IS NULL THEN RAISE EXCEPTION 'Existing Office Team schemas are required'; END IF;
END $$;
CREATE SCHEMA IF NOT EXISTS office_private;

CREATE TABLE public.office_health_admin_settings(
 workspace_id uuid PRIMARY KEY REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,
 jurisdiction text NOT NULL DEFAULT 'tanzania_mainland' CHECK(jurisdiction IN ('tanzania_mainland','zanzibar','other')),
 display_name text NOT NULL DEFAULT 'Health facility network', timezone_name text NOT NULL DEFAULT 'Africa/Dar_es_Salaam',
 key_config jsonb, clinical_data_enabled boolean NOT NULL DEFAULT false,
 storage_review_state text NOT NULL DEFAULT 'unverified' CHECK(storage_review_state IN ('unverified','approved')),
 version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.office_health_admin_staff_roles(workspace_id uuid NOT NULL,user_id uuid NOT NULL,health_role text NOT NULL CHECK(health_role IN('health_admin','facility_manager','registration_clerk','triage_nurse','clinician','lab_staff','pharmacist','ward_nurse','billing_clerk','credentialing_officer','privacy_officer','health_auditor','health_viewer','unassigned')),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE public.office_health_admin_staff_facility_scopes(workspace_id uuid NOT NULL,user_id uuid NOT NULL,facility_id uuid NOT NULL,department_id uuid,active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE NULLS NOT DISTINCT (workspace_id,user_id,facility_id,department_id));
CREATE TABLE public.office_health_admin_audit_log(audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL,actor_id uuid,facility_id uuid,department_id uuid,resource text NOT NULL,action text NOT NULL,entity_id uuid,purpose_code text,entity_count integer NOT NULL DEFAULT 1 CHECK(entity_count>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.office_health_admin_request_dedup(workspace_id uuid NOT NULL,idempotency_key uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,idempotency_key));
CREATE TABLE public.office_health_admin_facilities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,facility_code text NOT NULL,display_name text NOT NULL,facility_type text NOT NULL,status text NOT NULL DEFAULT 'draft',district text NOT NULL,region text NOT NULL,ownership text NOT NULL,official_reference text,source_url text,version bigint NOT NULL DEFAULT 1,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,facility_code));
CREATE TABLE public.office_health_admin_departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,facility_id uuid NOT NULL,code text NOT NULL,display_name text NOT NULL,status text NOT NULL DEFAULT 'active',version bigint NOT NULL DEFAULT 1,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,facility_id,code));
DO $x$ DECLARE n text; names text[]:=ARRAY['licenses','staff_credentials','patients','duplicate_cases','appointments','encounters','queue_entries','triage_events','clinical_records','diagnostic_orders','specimens','diagnostic_results','medication_orders','medication_administrations','wards','beds','admissions','bed_assignments','transfers','procedures','discharges','follow_ups','invoices','payments','payer_accreditations','claims','claim_events','medicine_items','medicine_lots','stock_movements','replenishment_requests','assets','asset_maintenance','privacy_incidents','data_requests','disclosures','external_workflows','evidence']; BEGIN FOREACH n IN ARRAY names LOOP EXECUTE format('CREATE TABLE public.office_health_admin_%I(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,facility_id uuid,department_id uuid,patient_id uuid,encounter_id uuid,order_id uuid,invoice_id uuid,admission_id uuid,bed_id uuid,item_id uuid,lot_id uuid,asset_id uuid,entity_id uuid,claim_id uuid,status text NOT NULL DEFAULT ''draft'',kind text NOT NULL DEFAULT ''record'',display_label text NOT NULL DEFAULT '''',official_reference text,source_url text,amount_tzs numeric(20,2),quantity numeric(24,6),nonce bytea,ciphertext bytea,metadata jsonb NOT NULL DEFAULT ''{}'',version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((nonce IS NULL AND ciphertext IS NULL) OR (octet_length(nonce)=12 AND octet_length(ciphertext)>=16)),CHECK(amount_tzs IS NULL OR amount_tzs>=0),CHECK(quantity IS NULL OR quantity>=0))',n); END LOOP; END $x$;
CREATE TABLE public.office_health_admin_patient_blind_indexes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,patient_id uuid NOT NULL,index_type text NOT NULL CHECK(index_type IN('facility_mrn','national_id','passport','phone')),digest bytea NOT NULL CHECK(octet_length(digest)=32),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,index_type,digest));
CREATE TABLE public.office_health_admin_private_payloads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,facility_id uuid,department_id uuid,patient_id uuid,nonce bytea NOT NULL CHECK(octet_length(nonce)=12),ciphertext bytea NOT NULL CHECK(octet_length(ciphertext)>=16),version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,entity_type,entity_id));

CREATE OR REPLACE FUNCTION office_private.health_context(w uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN IF auth.uid() IS NULL OR NOT office_private.is_active_member(w) OR NOT EXISTS(SELECT 1 FROM public.office_industry_spaces WHERE workspace_id=w AND industry_id='healthcare-admin') THEN RAISE EXCEPTION 'Health Office membership required' USING ERRCODE='42501'; END IF; IF office_private.is_admin(w) THEN RETURN 'health_admin'; END IF; SELECT health_role INTO r FROM public.office_health_admin_staff_roles WHERE workspace_id=w AND user_id=auth.uid() AND active; RETURN coalesce(r,'unassigned');END$$;
CREATE OR REPLACE FUNCTION office_private.health_role_ok(r text,a text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$SELECT CASE r
 WHEN 'health_admin' THEN a IN('settings','facility_admin','staff_roles','reports','audit','export')
 WHEN 'facility_manager' THEN a IN('settings','facility_admin','licenses','asset_admin','inventory','reports')
 WHEN 'registration_clerk' THEN a IN('settings','patient_registration','patient_identity_read','appointments','encounters')
 WHEN 'triage_nurse' THEN a IN('settings','patient_identity_read','triage','appointments','encounters')
 WHEN 'clinician' THEN a IN('settings','patient_registration','patient_identity_read','clinical_notes','diagnostic_orders','diagnostic_results','medication_orders','procedures','discharge','encounters','inpatient')
 WHEN 'lab_staff' THEN a IN('settings','patient_identity_read','diagnostic_orders','diagnostic_results')
 WHEN 'pharmacist' THEN a IN('settings','patient_identity_read','pharmacy_dispense','inventory','medication_orders')
 WHEN 'ward_nurse' THEN a IN('settings','patient_identity_read','inpatient','medication_admin')
 WHEN 'billing_clerk' THEN a IN('settings','patient_identity_read','billing','claims')
 WHEN 'credentialing_officer' THEN a IN('settings','credentialing','staff_roles')
 WHEN 'privacy_officer' THEN a IN('settings','privacy_ops','audit','evidence')
 WHEN 'health_auditor' THEN a IN('settings','audit','reports')
 WHEN 'health_viewer' THEN a IN('settings','reports')
 ELSE false END$$;

-- Exact action/resource matrix. Never infer a capability or table from a LIKE expression.
CREATE OR REPLACE FUNCTION office_private.health_action_capability(a text) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT CASE a
 WHEN 'configure_private_key' THEN 'settings' WHEN 'assign_staff_role' THEN 'staff_roles' WHEN 'assign_facility_scope' THEN 'staff_roles'
 WHEN 'save_facility' THEN 'facility_admin' WHEN 'transition_facility' THEN 'facility_admin' WHEN 'save_department' THEN 'facility_admin'
 WHEN 'save_license' THEN 'licenses' WHEN 'transition_license' THEN 'licenses' WHEN 'save_staff_credential' THEN 'credentialing' WHEN 'transition_staff_credential' THEN 'credentialing'
 WHEN 'register_patient' THEN 'patient_registration' WHEN 'update_patient_private' THEN 'patient_registration' WHEN 'review_duplicate_case' THEN 'patient_identity_read'
 WHEN 'create_appointment' THEN 'appointments' WHEN 'transition_appointment' THEN 'appointments' WHEN 'reschedule_appointment' THEN 'appointments'
 WHEN 'create_encounter' THEN 'encounters' WHEN 'transition_encounter' THEN 'encounters' WHEN 'assign_queue_entry' THEN 'triage' WHEN 'record_triage' THEN 'triage' WHEN 'save_clinical_record' THEN 'clinical_notes'
 WHEN 'create_diagnostic_order' THEN 'diagnostic_orders' WHEN 'transition_diagnostic_order' THEN 'diagnostic_orders' WHEN 'create_specimen' THEN 'diagnostic_orders' WHEN 'record_specimen_handoff' THEN 'diagnostic_orders' WHEN 'record_diagnostic_result' THEN 'diagnostic_results' WHEN 'approve_diagnostic_result' THEN 'diagnostic_results' WHEN 'deliver_diagnostic_result' THEN 'diagnostic_results'
 WHEN 'create_medication_order' THEN 'medication_orders' WHEN 'transition_medication_order' THEN 'medication_orders' WHEN 'record_medication_administration' THEN 'medication_admin'
 WHEN 'save_ward' THEN 'inpatient' WHEN 'save_bed' THEN 'inpatient' WHEN 'admit_patient' THEN 'inpatient' WHEN 'assign_bed' THEN 'inpatient' WHEN 'transfer_patient' THEN 'inpatient'
 WHEN 'save_procedure' THEN 'procedures' WHEN 'transition_procedure' THEN 'procedures' WHEN 'save_discharge' THEN 'discharge' WHEN 'finalize_discharge' THEN 'discharge' WHEN 'save_follow_up' THEN 'discharge'
 WHEN 'save_invoice' THEN 'billing' WHEN 'record_payment' THEN 'billing' WHEN 'save_payer_accreditation' THEN 'billing' WHEN 'create_claim' THEN 'claims' WHEN 'transition_claim' THEN 'claims' WHEN 'record_claim_response' THEN 'claims'
 WHEN 'save_medicine_item' THEN 'inventory' WHEN 'receive_medicine_lot' THEN 'inventory' WHEN 'record_stock_movement' THEN 'inventory' WHEN 'quarantine_medicine_lot' THEN 'inventory' WHEN 'dispose_medicine_lot' THEN 'inventory' WHEN 'create_replenishment_request' THEN 'inventory' WHEN 'transition_replenishment_request' THEN 'inventory'
 WHEN 'save_asset' THEN 'asset_admin' WHEN 'record_asset_maintenance' THEN 'asset_admin' WHEN 'save_privacy_incident' THEN 'privacy_ops' WHEN 'transition_privacy_incident' THEN 'privacy_ops' WHEN 'save_data_request' THEN 'privacy_ops' WHEN 'transition_data_request' THEN 'privacy_ops' WHEN 'log_disclosure' THEN 'privacy_ops' WHEN 'save_external_workflow' THEN 'evidence' WHEN 'link_evidence' THEN 'evidence' WHEN 'supersede_evidence' THEN 'evidence' WHEN 'audit_sensitive_export' THEN 'export' ELSE NULL END$$;
CREATE OR REPLACE FUNCTION office_private.health_resource_capability(r text) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT CASE r
 WHEN 'settings' THEN 'settings' WHEN 'facilities' THEN 'facility_admin' WHEN 'departments' THEN 'facility_admin' WHEN 'licenses' THEN 'licenses' WHEN 'staff_roles' THEN 'staff_roles' WHEN 'staff_credentials' THEN 'credentialing' WHEN 'medicine_items' THEN 'inventory' WHEN 'medicine_lots' THEN 'inventory' WHEN 'stock_movements' THEN 'inventory' WHEN 'replenishment_requests' THEN 'inventory' WHEN 'assets' THEN 'asset_admin' WHEN 'asset_maintenance' THEN 'asset_admin' WHEN 'privacy_incidents' THEN 'privacy_ops' WHEN 'data_requests' THEN 'privacy_ops' WHEN 'disclosures' THEN 'privacy_ops' WHEN 'external_workflows' THEN 'evidence' WHEN 'evidence' THEN 'evidence' WHEN 'audit' THEN 'audit' WHEN 'facility_report' THEN 'reports' WHEN 'clinical_report' THEN 'clinical_notes' WHEN 'diagnostic_report' THEN 'diagnostic_results' WHEN 'pharmacy_report' THEN 'pharmacy_dispense' WHEN 'inpatient_report' THEN 'inpatient' WHEN 'billing_report' THEN 'billing' WHEN 'claims_report' THEN 'claims' WHEN 'compliance_report' THEN 'reports' WHEN 'staff_report' THEN 'staff_roles'
 WHEN 'patients' THEN 'patient_identity_read' WHEN 'patient_private' THEN 'patient_identity_read' WHEN 'patient_matches' THEN 'patient_identity_read' WHEN 'duplicate_cases' THEN 'patient_identity_read' WHEN 'appointments' THEN 'appointments' WHEN 'encounters' THEN 'encounters' WHEN 'queue_entries' THEN 'triage' WHEN 'triage_events' THEN 'triage' WHEN 'clinical_records' THEN 'clinical_notes' WHEN 'diagnostic_orders' THEN 'diagnostic_orders' WHEN 'specimens' THEN 'diagnostic_orders' WHEN 'diagnostic_results' THEN 'diagnostic_results' WHEN 'medication_orders' THEN 'medication_orders' WHEN 'medication_administrations' THEN 'medication_admin' WHEN 'wards' THEN 'inpatient' WHEN 'beds' THEN 'inpatient' WHEN 'admissions' THEN 'inpatient' WHEN 'bed_assignments' THEN 'inpatient' WHEN 'transfers' THEN 'inpatient' WHEN 'procedures' THEN 'procedures' WHEN 'discharges' THEN 'discharge' WHEN 'follow_ups' THEN 'discharge' WHEN 'invoices' THEN 'billing' WHEN 'payments' THEN 'billing' WHEN 'payer_accreditations' THEN 'billing' WHEN 'claims' THEN 'claims' WHEN 'claim_events' THEN 'claims' ELSE NULL END$$;
CREATE OR REPLACE FUNCTION office_private.health_scope_ok(w uuid,f uuid,d uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT office_private.is_admin(w) OR (f IS NOT NULL AND EXISTS(SELECT 1 FROM public.office_health_admin_staff_facility_scopes s WHERE s.workspace_id=w AND s.user_id=auth.uid() AND s.facility_id=f AND s.active AND (s.department_id IS NULL OR s.department_id=d)))$$;
CREATE OR REPLACE FUNCTION office_private.health_validate_payload(a text,p jsonb) RETURNS void LANGUAGE plpgsql IMMUTABLE AS $$DECLARE k text; child jsonb; allowed text[]; bad text[]:=ARRAY['metadata','phone','email','dob','diagnosis','diagnoses','symptom','symptoms','narrative','note','notes','address','passport','national_id','mrn','name','full_name','first_name','last_name','allergies','medical_history','medication','medications','prescription','prescriptions']; BEGIN IF jsonb_typeof(p)<>'object' THEN RAISE EXCEPTION 'Object payload required' USING ERRCODE='22023'; END IF; PERFORM office_private.health_validate_json_keys(p,a); allowed:=CASE a
 WHEN 'configure_private_key' THEN ARRAY['key_config','expected_version'] WHEN 'assign_staff_role' THEN ARRAY['id','user_id','role','expected_version'] WHEN 'assign_facility_scope' THEN ARRAY['id','staff_role_id','facility_id','department_id','expected_version'] WHEN 'save_facility' THEN ARRAY['id','expected_version','facility_code','display_name','facility_type','district','region','ownership','state','source_url','official_reference'] WHEN 'transition_facility' THEN ARRAY['id','expected_version','state','reason'] WHEN 'save_department' THEN ARRAY['id','facility_id','expected_version','name','code','state'] WHEN 'save_license' THEN ARRAY['id','facility_id','expected_version','authority','license_kind','reference','issue_date','due_date','status','official_url'] WHEN 'transition_license' THEN ARRAY['id','expected_version','status','reason'] WHEN 'save_staff_credential' THEN ARRAY['id','facility_id','expected_version','staff_code','profession','council','issue_date','expiry_date','state','verifier_source','verifier_reference','nonce','ciphertext'] WHEN 'transition_staff_credential' THEN ARRAY['id','expected_version','state','reason'] WHEN 'register_patient' THEN ARRAY['id','facility_id','expected_version','nonce','ciphertext','blind_indexes'] WHEN 'update_patient_private' THEN ARRAY['id','expected_version','nonce','ciphertext','blind_indexes'] WHEN 'review_duplicate_case' THEN ARRAY['id','expected_version','status','reason'] WHEN 'create_appointment' THEN ARRAY['id','patient_id','facility_id','department_id','expected_version','appointment_type','scheduled_at','state'] WHEN 'transition_appointment' THEN ARRAY['id','expected_version','state','reason'] WHEN 'reschedule_appointment' THEN ARRAY['id','expected_version','scheduled_at','reason'] WHEN 'create_encounter' THEN ARRAY['id','patient_id','facility_id','department_id','expected_version','encounter_type','state'] WHEN 'transition_encounter' THEN ARRAY['id','expected_version','state','reason'] WHEN 'assign_queue_entry' THEN ARRAY['id','encounter_id','expected_version','queue','state'] WHEN 'record_triage' THEN ARRAY['id','encounter_id','expected_version','tool_name','tool_version','route_outcome','nonce','ciphertext'] WHEN 'save_clinical_record' THEN ARRAY['id','encounter_id','expected_version','record_type','nonce','ciphertext'] WHEN 'create_diagnostic_order' THEN ARRAY['id','encounter_id','expected_version','order_type','state','nonce','ciphertext'] WHEN 'transition_diagnostic_order' THEN ARRAY['id','expected_version','state','reason'] WHEN 'create_specimen' THEN ARRAY['id','order_id','expected_version','barcode','state'] WHEN 'record_specimen_handoff' THEN ARRAY['id','expected_version','state','mode','reason'] WHEN 'record_diagnostic_result' THEN ARRAY['id','order_id','expected_version','nonce','ciphertext'] WHEN 'approve_diagnostic_result' THEN ARRAY['id','expected_version','state','reason'] WHEN 'deliver_diagnostic_result' THEN ARRAY['id','expected_version','state','reason'] WHEN 'create_medication_order' THEN ARRAY['id','encounter_id','expected_version','state','nonce','ciphertext'] WHEN 'transition_medication_order' THEN ARRAY['id','expected_version','state','reason'] WHEN 'record_medication_administration' THEN ARRAY['id','order_id','expected_version','nonce','ciphertext'] WHEN 'save_ward' THEN ARRAY['id','facility_id','expected_version','name','state'] WHEN 'save_bed' THEN ARRAY['id','ward_id','expected_version','label','state'] WHEN 'admit_patient' THEN ARRAY['id','patient_id','expected_version','state','nonce','ciphertext'] WHEN 'assign_bed' THEN ARRAY['id','admission_id','bed_id','expected_version'] WHEN 'transfer_patient' THEN ARRAY['id','admission_id','expected_version','from_bed_id','to_bed_id','reason'] WHEN 'save_procedure' THEN ARRAY['id','encounter_id','expected_version','state','nonce','ciphertext'] WHEN 'transition_procedure' THEN ARRAY['id','expected_version','state','reason'] WHEN 'save_discharge' THEN ARRAY['id','encounter_id','expected_version','nonce','ciphertext'] WHEN 'finalize_discharge' THEN ARRAY['id','expected_version','state','reason'] WHEN 'save_follow_up' THEN ARRAY['id','patient_id','expected_version','state','nonce','ciphertext'] WHEN 'save_invoice' THEN ARRAY['id','patient_id','facility_id','expected_version','amount_tzs','state','nonce','ciphertext'] WHEN 'record_payment' THEN ARRAY['id','invoice_id','expected_version','amount_tzs','state','reference'] WHEN 'save_payer_accreditation' THEN ARRAY['id','facility_id','expected_version','payer','status','source_url','official_reference'] WHEN 'create_claim' THEN ARRAY['id','invoice_id','expected_version','amount_tzs','state','nonce','ciphertext'] WHEN 'transition_claim' THEN ARRAY['id','expected_version','state','reason'] WHEN 'record_claim_response' THEN ARRAY['id','claim_id','expected_version','state','reason','nonce','ciphertext'] WHEN 'save_medicine_item' THEN ARRAY['id','expected_version','product_code','product_description','strength','form','unit','regulator_reference','status'] WHEN 'receive_medicine_lot' THEN ARRAY['id','item_id','facility_id','expected_version','lot_reference','expiry_date','received_quantity','state'] WHEN 'record_stock_movement' THEN ARRAY['id','lot_id','expected_version','movement_type','quantity','movement_date','reason','reference'] WHEN 'quarantine_medicine_lot' THEN ARRAY['id','expected_version','reason'] WHEN 'dispose_medicine_lot' THEN ARRAY['id','expected_version','reason','disposal_date'] WHEN 'create_replenishment_request' THEN ARRAY['id','facility_id','item_id','expected_version','requested_quantity','state','reason','reference'] WHEN 'transition_replenishment_request' THEN ARRAY['id','expected_version','state','reason'] WHEN 'save_asset' THEN ARRAY['id','facility_id','expected_version','asset_type','state','source_reference'] WHEN 'record_asset_maintenance' THEN ARRAY['id','asset_id','expected_version','state','maintenance_date','reason'] WHEN 'save_privacy_incident' THEN ARRAY['id','expected_version','incident_reference','incident_date','severity','status','source_reference'] WHEN 'transition_privacy_incident' THEN ARRAY['id','expected_version','status','reason'] WHEN 'save_data_request' THEN ARRAY['id','expected_version','request_type','request_date','status','reference'] WHEN 'transition_data_request' THEN ARRAY['id','expected_version','status','reason'] WHEN 'log_disclosure' THEN ARRAY['id','expected_version','recipient_category','purpose','disclosure_date','outcome','reference'] WHEN 'save_external_workflow' THEN ARRAY['id','expected_version','authority','workflow_type','state','source_url','reference'] WHEN 'link_evidence' THEN ARRAY['id','expected_version','entity_type','entity_id','label','source_url','official_reference','status'] WHEN 'supersede_evidence' THEN ARRAY['id','expected_version','reason'] WHEN 'audit_sensitive_export' THEN ARRAY['resource','entity_ids','format','purpose_code'] ELSE ARRAY[]::text[] END;
 IF a<>'audit_sensitive_export' AND NOT (p ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='22023'; END IF; FOR k IN SELECT jsonb_object_keys(p) LOOP IF k='idempotency_key' THEN CONTINUE; END IF; IF NOT (k=ANY(allowed)) THEN RAISE EXCEPTION 'Unknown health payload field: %',k USING ERRCODE='22023'; END IF; IF (lower(k)=ANY(bad) AND NOT (a IN ('save_department','save_facility','save_ward','save_bed') AND lower(k)='name')) OR k ~* '(phone|email|dob|diagnos|symptom|narrative|note|address|passport|national_id|mrn|full.?name|first.?name|last.?name|allerg|medical.?history|medicat|prescription)'  THEN RAISE EXCEPTION 'Plaintext sensitive field rejected' USING ERRCODE='22023'; END IF; END LOOP; IF p ? 'expected_version' AND (jsonb_typeof(p->'expected_version')<>'number' OR (p->>'expected_version') !~ '^[0-9]+$' OR (p->>'expected_version')::numeric>9223372036854775807) THEN RAISE EXCEPTION 'Invalid expected_version' USING ERRCODE='22023'; END IF; IF p ? 'id' AND (p->>'id') !~ '^[0-9a-fA-F-]{36}$' THEN RAISE EXCEPTION 'Invalid UUID' USING ERRCODE='22023'; END IF; IF p ? 'nonce' AND ((p->>'nonce') !~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' OR octet_length(decode(p->>'nonce','base64'))<>12) THEN RAISE EXCEPTION 'Invalid base64 nonce' USING ERRCODE='22023'; END IF; IF p ? 'ciphertext' AND ((p->>'ciphertext') !~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' OR octet_length(decode(p->>'ciphertext','base64'))<16) THEN RAISE EXCEPTION 'Invalid base64 ciphertext' USING ERRCODE='22023'; END IF; IF p ? 'amount_tzs' AND (jsonb_typeof(p->'amount_tzs')<>'number' OR (p->>'amount_tzs')::numeric<0 OR (p->>'amount_tzs') !~ '^[0-9]+(\.[0-9]{1,2})?$') THEN RAISE EXCEPTION 'Invalid amount_tzs' USING ERRCODE='22023'; END IF;
 IF a='configure_private_key' THEN
   IF NOT (jsonb_typeof(p->'key_config')='object') THEN RAISE EXCEPTION 'key_config object required' USING ERRCODE='22023'; END IF;
   FOR k IN SELECT jsonb_object_keys(p->'key_config') LOOP
     IF k NOT IN ('configured','version','key_version','derivation','iterations','salt','nonce','ciphertext','index_key_nonce','index_key_ciphertext') THEN RAISE EXCEPTION 'Unsupported key manifest field: %',k USING ERRCODE='22023'; END IF;
     IF k IN ('configured') AND jsonb_typeof(p->'key_config'->k)<>'boolean' THEN RAISE EXCEPTION 'Invalid key manifest boolean' USING ERRCODE='22023'; END IF;
     IF k IN ('version','key_version','iterations') AND (jsonb_typeof(p->'key_config'->k)<>'number' OR (p->'key_config'->>k) !~ '^[0-9]+$') THEN RAISE EXCEPTION 'Invalid key manifest number' USING ERRCODE='22023'; END IF;
     IF k IN ('derivation','salt','nonce','ciphertext','index_key_nonce','index_key_ciphertext') AND jsonb_typeof(p->'key_config'->k)<>'string' THEN RAISE EXCEPTION 'Invalid key manifest string' USING ERRCODE='22023'; END IF;
   END LOOP;
 END IF;
 IF p ? 'blind_indexes' THEN
   IF jsonb_typeof(p->'blind_indexes')<>'array' THEN RAISE EXCEPTION 'blind_indexes array required' USING ERRCODE='22023'; END IF;
   FOR child IN SELECT value FROM jsonb_array_elements(p->'blind_indexes') LOOP
     IF jsonb_typeof(child)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(child))<>2 OR NOT (child ? 'index_type') OR NOT (child ? 'digest') OR child->>'index_type' NOT IN ('facility_mrn','national_id','passport','phone') OR jsonb_typeof(child->'index_type')<>'string' OR jsonb_typeof(child->'digest')<>'string' OR (child->>'digest') !~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' OR octet_length(decode(child->>'digest','base64'))<>32 THEN RAISE EXCEPTION 'Unsupported blind index shape' USING ERRCODE='22023'; END IF;
   END LOOP;
 END IF; END$$;
CREATE OR REPLACE FUNCTION office_private.health_validate_json_keys(v jsonb,a text DEFAULT NULL) RETURNS void LANGUAGE plpgsql IMMUTABLE AS $$DECLARE k text; child jsonb; BEGIN IF jsonb_typeof(v)='object' THEN FOR k IN SELECT jsonb_object_keys(v) LOOP IF lower(k) IN ('metadata','patient_name','patient_number','patient_identifier','member_id','full_name','first_name','last_name','phone','phone_number','email','dob','date_of_birth','diagnosis','diagnoses','symptom','symptoms','narrative','note','notes','address','passport','passport_number','national_id','mrn','allergies','allergy','medical_history','medication','medications','prescription','prescriptions') OR (lower(k)='name' AND coalesce(a,'') NOT IN ('save_department','save_facility','save_ward','save_bed')) OR k ~* '(patient[_-]?(name|number|identifier)|member[_-]?id|full[_-]?name|first[_-]?name|last[_-]?name|phone|email|dob|date[_-]?of[_-]?birth|diagnos|symptom|narrative|note|address|passport|national[_-]?id|mrn|allerg|medical[_-]?history|medicat|prescription)'  THEN RAISE EXCEPTION 'Plaintext sensitive field rejected' USING ERRCODE='22023'; END IF; child:=v->k; IF jsonb_typeof(child) IN ('object','array') THEN PERFORM office_private.health_validate_json_keys(child,a); END IF; END LOOP; ELSIF jsonb_typeof(v)='array' THEN FOR child IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM office_private.health_validate_json_keys(child,a); END LOOP; END IF; END$$;
CREATE OR REPLACE FUNCTION office_private.health_validate_relationships(w uuid,a text,p jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE f uuid:=NULLIF(p->>'facility_id','')::uuid; d uuid:=NULLIF(p->>'department_id','')::uuid; cv bigint; ef uuid; ed uuid; ep uuid; es text; ofc uuid; od uuid; oe uuid; os text; invf uuid; invamt numeric; paid numeric; claimed numeric; req numeric; af uuid; ast text; cur uuid; tab text; rw uuid;
BEGIN
 IF f IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_facilities WHERE id=f AND workspace_id=w AND status NOT IN('inactive','archived')) THEN RAISE EXCEPTION 'Facility is outside workspace or inactive' USING ERRCODE='42501'; END IF;
 IF d IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_departments WHERE id=d AND workspace_id=w AND facility_id=f AND status NOT IN('inactive','archived')) THEN RAISE EXCEPTION 'Department is outside workspace or facility' USING ERRCODE='42501'; END IF;
 IF a IN('transition_license','transition_staff_credential','review_duplicate_case','transition_appointment','reschedule_appointment','transition_encounter','transition_diagnostic_order','record_specimen_handoff','approve_diagnostic_result','deliver_diagnostic_result','transition_medication_order','transition_procedure','finalize_discharge','transition_claim','quarantine_medicine_lot','dispose_medicine_lot','transition_replenishment_request','transition_privacy_incident','transition_data_request','supersede_evidence') THEN
  tab:=CASE a WHEN 'transition_facility' THEN 'facilities' WHEN 'transition_license' THEN 'licenses' WHEN 'transition_staff_credential' THEN 'staff_credentials' WHEN 'review_duplicate_case' THEN 'duplicate_cases' WHEN 'transition_appointment' THEN 'appointments' WHEN 'reschedule_appointment' THEN 'appointments' WHEN 'transition_encounter' THEN 'encounters' WHEN 'record_specimen_handoff' THEN 'specimens' WHEN 'transition_diagnostic_order' THEN 'diagnostic_orders' WHEN 'approve_diagnostic_result' THEN 'diagnostic_results' WHEN 'deliver_diagnostic_result' THEN 'diagnostic_results' WHEN 'transition_medication_order' THEN 'medication_orders' WHEN 'transition_procedure' THEN 'procedures' WHEN 'finalize_discharge' THEN 'discharges' WHEN 'transition_claim' THEN 'claims' WHEN 'quarantine_medicine_lot' THEN 'medicine_lots' WHEN 'dispose_medicine_lot' THEN 'medicine_lots' WHEN 'transition_replenishment_request' THEN 'replenishment_requests' WHEN 'transition_privacy_incident' THEN 'privacy_incidents' WHEN 'transition_data_request' THEN 'data_requests' ELSE 'evidence' END;
  EXECUTE format('SELECT workspace_id,facility_id FROM public.office_health_admin_%I WHERE id=$1',tab) INTO rw,f USING (p->>'id'); IF rw IS NULL OR rw<>w THEN RAISE EXCEPTION 'Referenced transition row is outside workspace' USING ERRCODE='42501'; END IF; IF f IS NULL THEN p:=jsonb_set(p,'{facility_id}',to_jsonb(f::text)); END IF;
 END IF;
 IF a IN('assign_queue_entry','record_triage','save_clinical_record','create_diagnostic_order','create_medication_order','save_procedure','save_discharge') THEN
  SELECT facility_id,department_id,patient_id,status INTO ef,ed,ep,es FROM public.office_health_admin_encounters WHERE id=(p->>'encounter_id')::uuid AND workspace_id=w; IF ef IS NULL OR es IN('cancelled','closed','inactive','archived') THEN RAISE EXCEPTION 'Encounter is outside workspace or inactive' USING ERRCODE='42501'; END IF; IF f IS NULL THEN p:=jsonb_set(p,'{facility_id}',to_jsonb(ef::text)); f:=ef; ELSIF f<>ef THEN RAISE EXCEPTION 'Encounter facility mismatch' USING ERRCODE='42501'; END IF; IF d IS NULL AND ed IS NOT NULL THEN p:=jsonb_set(p,'{department_id}',to_jsonb(ed::text)); d:=ed; ELSIF d IS NOT NULL AND d<>ed THEN RAISE EXCEPTION 'Encounter department mismatch' USING ERRCODE='42501'; END IF; IF ep IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_patients WHERE id=ep AND workspace_id=w AND facility_id=ef AND status NOT IN('inactive','archived')) THEN RAISE EXCEPTION 'Encounter patient is outside scope' USING ERRCODE='42501'; END IF;
 END IF;
 IF a IN('create_specimen','record_diagnostic_result','record_medication_administration') THEN
  IF a='record_medication_administration' THEN SELECT facility_id,department_id,encounter_id,status INTO ofc,od,oe,os FROM public.office_health_admin_medication_orders WHERE id=(p->>'order_id')::uuid AND workspace_id=w; ELSE SELECT facility_id,department_id,encounter_id,status INTO ofc,od,oe,os FROM public.office_health_admin_diagnostic_orders WHERE id=(p->>'order_id')::uuid AND workspace_id=w; END IF; IF ofc IS NULL OR os IN('cancelled','closed','inactive','archived') THEN RAISE EXCEPTION 'Order is outside workspace or inactive' USING ERRCODE='42501'; END IF; IF f IS NULL THEN p:=jsonb_set(p,'{facility_id}',to_jsonb(ofc::text)); f:=ofc; ELSIF f<>ofc THEN RAISE EXCEPTION 'Order facility mismatch' USING ERRCODE='42501'; END IF; IF d IS NULL AND od IS NOT NULL THEN p:=jsonb_set(p,'{department_id}',to_jsonb(od::text)); END IF; IF oe IS NULL OR NOT EXISTS(SELECT 1 FROM public.office_health_admin_encounters WHERE id=oe AND workspace_id=w AND facility_id=ofc AND status NOT IN('cancelled','closed','inactive','archived')) THEN RAISE EXCEPTION 'Order encounter chain is invalid' USING ERRCODE='42501'; END IF;
 END IF;
 IF a='update_patient_private' THEN SELECT facility_id,department_id INTO f,d FROM public.office_health_admin_patients WHERE id=(p->>'id')::uuid AND workspace_id=w AND status NOT IN('inactive','archived'); IF f IS NULL THEN RAISE EXCEPTION 'Patient is outside workspace/facility' USING ERRCODE='42501'; END IF; p:=jsonb_set(jsonb_set(p,'{facility_id}',to_jsonb(f::text)),'{department_id}',coalesce(to_jsonb(d::text),'null'::jsonb)); END IF;
 IF a='record_claim_response' THEN SELECT facility_id,department_id,version INTO f,d,cv FROM public.office_health_admin_claims WHERE id=(p->>'claim_id')::uuid AND workspace_id=w AND status NOT IN('inactive','archived'); IF f IS NULL THEN RAISE EXCEPTION 'Claim is outside workspace/facility' USING ERRCODE='42501'; END IF; IF cv<>(p->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale claim version' USING ERRCODE='40001'; END IF; p:=jsonb_set(jsonb_set(p,'{facility_id}',to_jsonb(f::text)),'{department_id}',coalesce(to_jsonb(d::text),'null'::jsonb)); END IF;
 IF a IN('create_appointment','create_encounter','register_patient','save_invoice','save_follow_up','admit_patient') AND p ? 'patient_id' AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_patients WHERE id=(p->>'patient_id')::uuid AND workspace_id=w AND facility_id=f AND status NOT IN('inactive','archived')) THEN RAISE EXCEPTION 'Patient is outside workspace/facility' USING ERRCODE='42501'; END IF;
 IF a IN('record_payment','create_claim') THEN SELECT facility_id,amount_tzs INTO invf,invamt FROM public.office_health_admin_invoices WHERE id=(p->>'invoice_id')::uuid AND workspace_id=w; IF invf IS NULL OR invf<>f THEN RAISE EXCEPTION 'Invoice is outside workspace/facility' USING ERRCODE='42501'; END IF; req:=coalesce(NULLIF(p->>'amount_tzs','')::numeric,0); SELECT coalesce(sum(amount_tzs),0) INTO paid FROM public.office_health_admin_payments WHERE workspace_id=w AND invoice_id=(p->>'invoice_id')::uuid AND status NOT IN('void','cancelled'); SELECT coalesce(sum(amount_tzs),0) INTO claimed FROM public.office_health_admin_claims WHERE workspace_id=w AND invoice_id=(p->>'invoice_id')::uuid AND status NOT IN('rejected','cancelled'); IF req<0 OR req>invamt-paid-(CASE WHEN a='create_claim' THEN claimed ELSE 0 END) THEN RAISE EXCEPTION 'Amount exceeds invoice outstanding eligible balance' USING ERRCODE='22023'; END IF; END IF;
 IF a='save_bed' THEN SELECT facility_id INTO af FROM public.office_health_admin_wards WHERE id=(p->>'ward_id')::uuid AND workspace_id=w AND status NOT IN('inactive','archived'); IF af IS NULL OR (f IS NOT NULL AND f<>af) THEN RAISE EXCEPTION 'Ward is outside workspace/facility' USING ERRCODE='42501'; END IF; p:=jsonb_set(p,'{facility_id}',to_jsonb(af::text)); END IF;
 IF a IN('assign_bed','transfer_patient') THEN SELECT facility_id,status INTO af,ast FROM public.office_health_admin_admissions WHERE id=(p->>'admission_id')::uuid AND workspace_id=w; IF af IS NULL OR ast IN('inactive','archived','discharged') THEN RAISE EXCEPTION 'Admission is outside workspace or inactive' USING ERRCODE='42501'; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_health_admin_beds WHERE id=coalesce(NULLIF(p->>'bed_id','')::uuid,NULLIF(p->>'to_bed_id','')::uuid) AND workspace_id=w AND facility_id=af AND status IN('available','active','draft')) THEN RAISE EXCEPTION 'Bed is outside workspace/facility or unavailable' USING ERRCODE='42501'; END IF; IF a='transfer_patient' THEN SELECT bed_id INTO cur FROM public.office_health_admin_bed_assignments WHERE workspace_id=w AND admission_id=(p->>'admission_id')::uuid AND status IN('assigned','active') ORDER BY created_at DESC LIMIT 1; IF cur IS NULL OR cur<>(p->>'from_bed_id')::uuid THEN RAISE EXCEPTION 'From-bed is not current assignment' USING ERRCODE='42501'; END IF; END IF; p:=jsonb_set(p,'{facility_id}',to_jsonb(af::text)); END IF;
 IF a='receive_medicine_lot' AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_medicine_items WHERE id=(p->>'item_id')::uuid AND workspace_id=w) THEN RAISE EXCEPTION 'Medicine item is outside workspace' USING ERRCODE='42501'; END IF;
 IF a='record_stock_movement' AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_medicine_lots WHERE id=(p->>'lot_id')::uuid AND workspace_id=w) THEN RAISE EXCEPTION 'Medicine lot is outside workspace' USING ERRCODE='42501'; END IF;
 IF a='record_asset_maintenance' THEN SELECT facility_id,department_id INTO af,od FROM public.office_health_admin_assets WHERE id=(p->>'asset_id')::uuid AND workspace_id=w AND status NOT IN('inactive','archived'); IF af IS NULL THEN RAISE EXCEPTION 'Asset is outside workspace or inactive' USING ERRCODE='42501'; END IF; IF f IS NOT NULL AND f<>af THEN RAISE EXCEPTION 'Asset facility mismatch' USING ERRCODE='42501'; END IF; IF d IS NOT NULL AND od IS DISTINCT FROM d THEN RAISE EXCEPTION 'Asset department mismatch' USING ERRCODE='42501'; END IF; p:=jsonb_set(jsonb_set(p,'{facility_id}',to_jsonb(af::text)),'{department_id}',coalesce(to_jsonb(od::text),'null'::jsonb)); f:=af; d:=od; END IF;
 IF a='link_evidence' AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_evidence e WHERE e.id=(p->>'id')::uuid AND e.workspace_id=w) THEN
  IF NOT ((p->>'entity_type')='privacy_incident' AND EXISTS(SELECT 1 FROM public.office_health_admin_privacy_incidents x WHERE x.id=(p->>'entity_id')::uuid AND x.workspace_id=w))
  THEN RAISE EXCEPTION 'Evidence entity is outside workspace or unsupported' USING ERRCODE='42501'; END IF;
 END IF;
 IF a='assign_facility_scope' AND (NOT EXISTS(SELECT 1 FROM public.office_health_admin_staff_roles WHERE workspace_id=w AND user_id=(p->>'staff_role_id')::uuid AND active) OR NOT EXISTS(SELECT 1 FROM public.office_health_admin_facilities WHERE id=(p->>'facility_id')::uuid AND workspace_id=w AND status NOT IN('inactive','archived')) OR (p ? 'department_id' AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_departments WHERE id=(p->>'department_id')::uuid AND workspace_id=w AND facility_id=(p->>'facility_id')::uuid))) THEN RAISE EXCEPTION 'Facility scope requires active workspace staff and facility/department' USING ERRCODE='42501'; END IF;
 RETURN p;
END$$;
CREATE OR REPLACE FUNCTION office_private.health_gate(w uuid) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$BEGIN IF NOT EXISTS(SELECT 1 FROM public.office_health_admin_settings WHERE workspace_id=w AND clinical_data_enabled AND storage_review_state='approved') THEN RAISE EXCEPTION 'Clinical storage review is not approved' USING ERRCODE='55000'; END IF;END$$;
CREATE OR REPLACE FUNCTION office_private.health_action_requires_gate(a text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$SELECT a IN('register_patient','update_patient_private','review_duplicate_case','create_appointment','transition_appointment','reschedule_appointment','create_encounter','transition_encounter','assign_queue_entry','record_triage','save_clinical_record','create_diagnostic_order','transition_diagnostic_order','create_specimen','record_specimen_handoff','record_diagnostic_result','approve_diagnostic_result','deliver_diagnostic_result','create_medication_order','transition_medication_order','record_medication_administration','admit_patient','assign_bed','transfer_patient','save_procedure','transition_procedure','save_discharge','finalize_discharge','save_follow_up','save_invoice','record_payment','create_claim','transition_claim','record_claim_response');$$;
CREATE OR REPLACE FUNCTION office_private.health_authorize(w uuid,a text,phi boolean DEFAULT false) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN r:=office_private.health_context(w);IF NOT office_private.health_role_ok(r,a) THEN RAISE EXCEPTION 'Health capability required' USING ERRCODE='42501';END IF;IF phi THEN PERFORM office_private.health_gate(w);END IF;RETURN r;END$$;
CREATE OR REPLACE FUNCTION office_private.health_audit_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'Health audit is immutable' USING ERRCODE='55000';END$$;
CREATE TRIGGER health_audit_immutable BEFORE UPDATE OR DELETE ON public.office_health_admin_audit_log FOR EACH ROW EXECUTE FUNCTION office_private.health_audit_immutable();

CREATE OR REPLACE FUNCTION public.office_health_admin_read(p_workspace_id uuid,p_resource text,p_filter jsonb DEFAULT '{}'::jsonb,p_limit int DEFAULT 200,p_offset int DEFAULT 0,p_purpose_code text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r text; rows jsonb; total bigint; lim int:=least(greatest(coalesce(p_limit,200),1),200); tab text; phi boolean; purpose text[]:=ARRAY['registration','appointment','direct_care','triage','laboratory','pharmacy','ward_care','billing','claims','credential_review','privacy_review','compliance_review','aggregate_reporting','authorized_export']; resources text[]:=ARRAY['bootstrap','settings','facilities','departments','patients','patient_private','patient_matches','duplicate_cases','appointments','encounters','queue_entries','triage_events','clinical_records','diagnostic_orders','specimens','diagnostic_results','medication_orders','medication_administrations','wards','beds','admissions','transfers','procedures','discharges','follow_ups','invoices','payments','payer_accreditations','claims','staff_roles','staff_credentials','licenses','medicine_items','medicine_lots','stock_movements','replenishment_requests','assets','asset_maintenance','privacy_incidents','data_requests','disclosures','external_workflows','evidence','audit','facility_report','clinical_report','diagnostic_report','pharmacy_report','inpatient_report','billing_report','claims_report','compliance_report','staff_report'];
BEGIN
 IF p_resource<>ALL(resources) OR jsonb_typeof(coalesce(p_filter,'{}'))<>'object' OR p_limit<1 OR p_limit>200 OR p_offset<0 THEN RAISE EXCEPTION 'Unknown health resource or invalid pagination' USING ERRCODE='22023';END IF;
 r:=office_private.health_context(p_workspace_id);
 IF p_resource='bootstrap' THEN RETURN jsonb_build_object('role',r,'clinical_data_enabled',coalesce((SELECT clinical_data_enabled FROM public.office_health_admin_settings WHERE workspace_id=p_workspace_id),false),'storage_review_state',coalesce((SELECT storage_review_state FROM public.office_health_admin_settings WHERE workspace_id=p_workspace_id),'unverified')); END IF;
 IF p_resource='settings' THEN PERFORM office_private.health_authorize(p_workspace_id,'settings'); IF p_purpose_code IS DISTINCT FROM 'aggregate_reporting' THEN RAISE EXCEPTION 'Valid settings read purpose required' USING ERRCODE='22023'; END IF; SELECT count(*) INTO total FROM public.office_health_admin_settings WHERE workspace_id=p_workspace_id; SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) INTO rows FROM (SELECT jurisdiction,display_name,timezone_name,clinical_data_enabled,storage_review_state,version,key_config FROM public.office_health_admin_settings WHERE workspace_id=p_workspace_id ORDER BY workspace_id LIMIT lim OFFSET p_offset) x; RETURN jsonb_build_object('rows',rows,'total_count',coalesce(total,0),'offset',p_offset,'limit',lim,'has_more',p_offset+jsonb_array_length(rows)<coalesce(total,0)); END IF;
 PERFORM office_private.health_authorize(p_workspace_id,office_private.health_resource_capability(p_resource),p_resource IN('patients','patient_private','patient_matches','duplicate_cases','appointments','encounters','queue_entries','triage_events','clinical_records','diagnostic_orders','specimens','diagnostic_results','medication_orders','medication_administrations','admissions','transfers','procedures','discharges','follow_ups','invoices','payments','payer_accreditations','claims','claim_events','clinical_report','diagnostic_report','pharmacy_report','inpatient_report','billing_report','claims_report')); IF p_resource NOT IN('bootstrap','settings') AND NOT office_private.health_scope_ok(p_workspace_id,NULLIF(p_filter->>'facility_id','')::uuid,NULLIF(p_filter->>'department_id','')::uuid) THEN RAISE EXCEPTION 'Active facility and department scope required' USING ERRCODE='42501'; END IF; IF p_resource IN('patients','patient_private','patient_matches','duplicate_cases','appointments','encounters','queue_entries','triage_events','clinical_records','diagnostic_orders','specimens','diagnostic_results','medication_orders','medication_administrations','admissions','transfers','procedures','discharges','follow_ups','claims','clinical_report','diagnostic_report','pharmacy_report','inpatient_report','billing_report','claims_report') AND (p_purpose_code IS NULL OR p_purpose_code<>ALL(purpose)) THEN RAISE EXCEPTION 'Valid read purpose required' USING ERRCODE='22023'; END IF;
 IF p_resource='patient_matches' THEN SELECT count(*) INTO total FROM public.office_health_admin_patient_blind_indexes i WHERE i.workspace_id=p_workspace_id AND (p_filter->>'index_type' IS NULL OR i.index_type=p_filter->>'index_type') AND (p_filter->>'digest' IS NULL OR i.digest=decode(p_filter->>'digest','base64')); SELECT coalesce(jsonb_agg(jsonb_build_object('id',i.id,'patient_id',i.patient_id,'index_type',i.index_type)), '[]'::jsonb) INTO rows FROM (SELECT * FROM public.office_health_admin_patient_blind_indexes i WHERE i.workspace_id=p_workspace_id AND (p_filter->>'index_type' IS NULL OR i.index_type=p_filter->>'index_type') AND (p_filter->>'digest' IS NULL OR i.digest=decode(p_filter->>'digest','base64')) ORDER BY i.created_at LIMIT lim OFFSET p_offset) i;
 ELSE
  tab:=CASE p_resource WHEN 'patient_private' THEN 'patients' WHEN 'facility_report' THEN 'facilities' WHEN 'clinical_report' THEN 'clinical_records' WHEN 'diagnostic_report' THEN 'diagnostic_results' WHEN 'pharmacy_report' THEN 'medication_orders' WHEN 'inpatient_report' THEN 'admissions' WHEN 'billing_report' THEN 'invoices' WHEN 'claims_report' THEN 'claims' WHEN 'compliance_report' THEN 'privacy_incidents' WHEN 'staff_report' THEN 'staff_roles' ELSE p_resource END;
  IF p_resource='audit' THEN SELECT count(*) INTO total FROM public.office_health_admin_audit_log WHERE workspace_id=p_workspace_id; SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) INTO rows FROM (SELECT audit_id,actor_id,facility_id,department_id,resource,action,entity_id,purpose_code,entity_count,created_at FROM public.office_health_admin_audit_log WHERE workspace_id=p_workspace_id ORDER BY created_at DESC LIMIT lim OFFSET p_offset) x;
  ELSIF p_resource='patient_private' THEN SELECT count(*) INTO total FROM public.office_health_admin_patients WHERE workspace_id=p_workspace_id; SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) INTO rows FROM (SELECT id,facility_id,department_id,nonce,ciphertext,version FROM public.office_health_admin_patients WHERE workspace_id=p_workspace_id ORDER BY created_at DESC LIMIT lim OFFSET p_offset) x;
  ELSE EXECUTE format('SELECT count(*) FROM public.office_health_admin_%I WHERE workspace_id=$1',tab) INTO total USING p_workspace_id; EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) FROM (SELECT * FROM public.office_health_admin_%I WHERE workspace_id=$1 ORDER BY created_at DESC LIMIT $2 OFFSET $3) x',tab) INTO rows USING p_workspace_id,lim,p_offset; END IF;
 END IF;
 INSERT INTO public.office_health_admin_audit_log(workspace_id,actor_id,resource,action,entity_count,purpose_code) VALUES(p_workspace_id,auth.uid(),p_resource,'read',greatest(jsonb_array_length(coalesce(rows,'[]')),1),p_purpose_code);
 RETURN jsonb_build_object('rows',coalesce(rows,'[]'),'total_count',coalesce(total,0),'offset',p_offset,'limit',lim,'has_more',p_offset+jsonb_array_length(coalesce(rows,'[]'))<coalesce(total,0));
END$$;

CREATE OR REPLACE FUNCTION office_private.health_action_metadata(a text,p jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(jsonb_object_agg(key,value ORDER BY key),'{}'::jsonb)
 FROM jsonb_each(p)
 WHERE key NOT IN ('id','expected_version','idempotency_key','key_config','nonce','ciphertext','blind_indexes','claim_id');
$$;
CREATE OR REPLACE FUNCTION office_private.health_action_display_label(a text,p jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(nullif(p->>'display_name',''),nullif(p->>'name',''),nullif(p->>'label',''),nullif(p->>'code',''),nullif(p->>'facility_code',''),nullif(p->>'license_kind',''),nullif(p->>'asset_type',''),a);
$$;
CREATE OR REPLACE FUNCTION public.office_health_admin_command(p_workspace_id uuid,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE role text; idem uuid; h text; prior_hash text; old text; result jsonb; eid uuid; expected bigint; current_version bigint; inv_f uuid; inv_d uuid; member_status text; tab text; export_tab text; export_id text; export_uuid uuid; export_exists boolean; export_ids jsonb; action_set text[]:=ARRAY['configure_private_key','assign_staff_role','assign_facility_scope','save_facility','transition_facility','save_department','save_license','transition_license','save_staff_credential','transition_staff_credential','register_patient','update_patient_private','review_duplicate_case','create_appointment','transition_appointment','reschedule_appointment','create_encounter','transition_encounter','assign_queue_entry','record_triage','save_clinical_record','create_diagnostic_order','transition_diagnostic_order','create_specimen','record_specimen_handoff','record_diagnostic_result','approve_diagnostic_result','deliver_diagnostic_result','create_medication_order','transition_medication_order','record_medication_administration','save_ward','save_bed','admit_patient','assign_bed','transfer_patient','save_procedure','transition_procedure','save_discharge','finalize_discharge','save_follow_up','save_invoice','record_payment','save_payer_accreditation','create_claim','transition_claim','record_claim_response','save_medicine_item','receive_medicine_lot','record_stock_movement','quarantine_medicine_lot','dispose_medicine_lot','create_replenishment_request','transition_replenishment_request','save_asset','record_asset_maintenance','save_privacy_incident','transition_privacy_incident','save_data_request','transition_data_request','log_disclosure','save_external_workflow','link_evidence','supersede_evidence','audit_sensitive_export']; phi boolean;
BEGIN
 IF p_action<>ALL(action_set) OR jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'Unknown health action or invalid payload' USING ERRCODE='22023'; END IF; IF office_private.health_action_requires_gate(p_action) THEN PERFORM office_private.health_gate(p_workspace_id); END IF; PERFORM office_private.health_validate_payload(p_action,p_payload);
 idem:=NULLIF(p_payload->>'idempotency_key','')::uuid; IF idem IS NULL THEN RAISE EXCEPTION 'idempotency_key required' USING ERRCODE='22023'; END IF;
 h:=encode(sha256(convert_to(p_action||':'||p_payload::text,'UTF8')),'hex'); SELECT request_hash,response::text INTO prior_hash,old FROM public.office_health_admin_request_dedup WHERE workspace_id=p_workspace_id AND idempotency_key=idem FOR UPDATE; IF old IS NOT NULL THEN IF h<>prior_hash THEN RAISE EXCEPTION 'Idempotency key payload mismatch' USING ERRCODE='23505'; END IF; RETURN old::jsonb; END IF;
 role:=office_private.health_context(p_workspace_id); PERFORM office_private.health_authorize(p_workspace_id,office_private.health_action_capability(p_action),office_private.health_action_requires_gate(p_action)); p_payload:=office_private.health_validate_relationships(p_workspace_id,p_action,p_payload); IF p_action<>'configure_private_key' AND NOT office_private.health_scope_ok(p_workspace_id,NULLIF(p_payload->>'facility_id','')::uuid,NULLIF(p_payload->>'department_id','')::uuid) AND p_action NOT IN('assign_staff_role','assign_facility_scope','save_facility','configure_private_key') THEN RAISE EXCEPTION 'Active facility and department scope required' USING ERRCODE='42501'; END IF; phi:=p_action IN('register_patient','update_patient_private','create_appointment','create_encounter','record_triage','save_clinical_record','create_diagnostic_order','create_specimen','record_specimen_handoff','record_diagnostic_result','approve_diagnostic_result','deliver_diagnostic_result','create_medication_order','transition_medication_order','record_medication_administration','admit_patient','assign_bed','transfer_patient','save_procedure','save_discharge','finalize_discharge','save_follow_up','save_invoice','record_payment','create_claim','transition_claim','record_claim_response','audit_sensitive_export');
 IF p_action='configure_private_key' THEN IF role<>'health_admin' THEN RAISE EXCEPTION 'Health Administration owner capability required' USING ERRCODE='42501'; END IF; PERFORM office_private.health_authorize(p_workspace_id,'settings'); IF (p_payload->'key_config') IS NULL OR jsonb_typeof(p_payload->'key_config')<>'object' THEN RAISE EXCEPTION 'key_config required' USING ERRCODE='22023'; END IF; SELECT version INTO current_version FROM public.office_health_admin_settings WHERE workspace_id=p_workspace_id FOR UPDATE; IF current_version IS NULL THEN RAISE EXCEPTION 'Health settings bootstrap missing' USING ERRCODE='55000'; END IF; IF (p_payload->>'expected_version')::bigint<>current_version THEN RAISE EXCEPTION 'Stale settings version' USING ERRCODE='40001'; END IF; UPDATE public.office_health_admin_settings SET key_config=p_payload->'key_config',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id RETURNING jsonb_build_object('id',workspace_id,'version',version,'configured',true) INTO result;
 ELSIF p_action IN('assign_staff_role','assign_facility_scope') THEN PERFORM office_private.health_authorize(p_workspace_id,'staff_roles'); IF p_action='assign_staff_role' THEN SELECT status INTO member_status FROM public.office_memberships WHERE workspace_id=p_workspace_id AND user_id=(p_payload->>'user_id')::uuid FOR UPDATE; IF member_status IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'Target must be an active workspace member' USING ERRCODE='42501'; END IF; SELECT version INTO current_version FROM public.office_health_admin_staff_roles WHERE workspace_id=p_workspace_id AND user_id=(p_payload->>'user_id')::uuid FOR UPDATE; IF current_version IS NULL THEN IF (p_payload->>'expected_version')::bigint<>0 THEN RAISE EXCEPTION 'Invalid staff role version' USING ERRCODE='40001'; END IF; INSERT INTO public.office_health_admin_staff_roles(workspace_id,user_id,health_role,version) VALUES(p_workspace_id,(p_payload->>'user_id')::uuid,p_payload->>'role',1) RETURNING jsonb_build_object('id',user_id,'version',version,'role',health_role) INTO result; ELSE IF (p_payload->>'expected_version')::bigint<>current_version THEN RAISE EXCEPTION 'Stale staff role version' USING ERRCODE='40001'; END IF; UPDATE public.office_health_admin_staff_roles SET health_role=p_payload->>'role',active=true,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND user_id=(p_payload->>'user_id')::uuid RETURNING jsonb_build_object('id',user_id,'version',version,'role',health_role) INTO result; END IF; ELSE INSERT INTO public.office_health_admin_staff_facility_scopes(workspace_id,user_id,facility_id,department_id) VALUES(p_workspace_id,(p_payload->>'staff_role_id')::uuid,(p_payload->>'facility_id')::uuid,NULLIF(p_payload->>'department_id','')::uuid) ON CONFLICT(workspace_id,user_id,facility_id,department_id) DO UPDATE SET active=true,version=office_health_admin_staff_facility_scopes.version+1,updated_at=now() RETURNING jsonb_build_object('id',user_id,'version',version) INTO result; END IF;
 ELSIF p_action IN('save_facility','transition_facility') THEN PERFORM office_private.health_authorize(p_workspace_id,'facility_admin'); eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid()); IF p_action='save_facility' THEN INSERT INTO public.office_health_admin_facilities(id,workspace_id,facility_code,display_name,facility_type,district,region,ownership,status,official_reference,source_url,created_by) VALUES(eid,p_workspace_id,p_payload->>'facility_code',p_payload->>'display_name',p_payload->>'facility_type',p_payload->>'district',p_payload->>'region',p_payload->>'ownership',coalesce(p_payload->>'state','draft'),p_payload->>'official_reference',p_payload->>'source_url',auth.uid()) ON CONFLICT(id) DO UPDATE SET display_name=excluded.display_name,facility_type=excluded.facility_type,district=excluded.district,region=excluded.region,ownership=excluded.ownership,status=excluded.status,version=office_health_admin_facilities.version+1,updated_at=now() RETURNING jsonb_build_object('id',id,'version',version,'status',status) INTO result; ELSE UPDATE public.office_health_admin_facilities SET status=p_payload->>'state',version=version+1,updated_at=now() WHERE id=(p_payload->>'id')::uuid AND workspace_id=p_workspace_id AND version=(p_payload->>'expected_version')::bigint RETURNING jsonb_build_object('id',id,'version',version,'status',status) INTO result; END IF;
 ELSIF p_action='save_department' THEN
  PERFORM office_private.health_authorize(p_workspace_id,'facility_admin');
  eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid());
  IF p_payload ? 'id' THEN
    SELECT version INTO current_version FROM public.office_health_admin_departments WHERE id=eid AND workspace_id=p_workspace_id FOR UPDATE;
    IF current_version IS NULL OR current_version<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale or outside-workspace department version' USING ERRCODE='40001'; END IF;
  ELSIF (p_payload->>'expected_version')::bigint<>0 THEN RAISE EXCEPTION 'Create expected_version must be zero' USING ERRCODE='40001'; END IF;
  INSERT INTO public.office_health_admin_departments(id,workspace_id,facility_id,code,display_name,status,created_by) VALUES(eid,p_workspace_id,(p_payload->>'facility_id')::uuid,p_payload->>'code',p_payload->>'name',coalesce(p_payload->>'state','active'),auth.uid()) ON CONFLICT(id) DO UPDATE SET facility_id=excluded.facility_id,code=excluded.code,display_name=excluded.display_name,status=excluded.status,version=office_health_admin_departments.version+1,updated_at=now() WHERE office_health_admin_departments.workspace_id=p_workspace_id AND office_health_admin_departments.version=(p_payload->>'expected_version')::bigint RETURNING jsonb_build_object('id',id,'version',version,'status',status) INTO result;
 ELSIF p_action='record_claim_response' THEN
  PERFORM office_private.health_authorize(p_workspace_id,'claims',true);
  SELECT facility_id,department_id,version INTO inv_f,inv_d,current_version FROM public.office_health_admin_claims WHERE id=(p_payload->>'claim_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
  IF current_version IS NULL OR current_version<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale or outside-workspace claim version' USING ERRCODE='40001'; END IF;
  eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid());
  INSERT INTO public.office_health_admin_claim_events(id,workspace_id,facility_id,department_id,claim_id,status,kind,display_label,nonce,ciphertext,metadata,created_by) VALUES(eid,p_workspace_id,inv_f,inv_d,(p_payload->>'claim_id')::uuid,coalesce(p_payload->>'state','recorded'),'claim_event',p_payload->>'reason',decode(p_payload->>'nonce','base64'),decode(p_payload->>'ciphertext','base64'),office_private.health_action_metadata(p_action,p_payload),auth.uid());
  UPDATE public.office_health_admin_claims SET status=coalesce(p_payload->>'state',status),version=version+1,updated_at=now() WHERE id=(p_payload->>'claim_id')::uuid AND workspace_id=p_workspace_id;
  result:=jsonb_build_object('id',eid,'version',1,'parent_version',current_version+1,'status',coalesce(p_payload->>'state','recorded'),'claim_id',(p_payload->>'claim_id')::uuid);
 ELSIF p_action IN('save_department','save_license','save_staff_credential','save_ward','save_bed','save_medicine_item','receive_medicine_lot','save_payer_accreditation','save_asset','save_privacy_incident','save_data_request','log_disclosure','save_external_workflow','link_evidence','create_replenishment_request','save_invoice','create_claim','save_follow_up','create_appointment','create_encounter','assign_queue_entry','record_triage','save_clinical_record','create_diagnostic_order','create_specimen','record_diagnostic_result','create_medication_order','record_medication_administration','admit_patient','save_procedure','save_discharge') THEN
  PERFORM office_private.health_authorize(p_workspace_id,office_private.health_action_capability(p_action),phi);
  tab:=CASE p_action WHEN 'save_department' THEN 'departments' WHEN 'save_license' THEN 'licenses' WHEN 'save_staff_credential' THEN 'staff_credentials' WHEN 'save_ward' THEN 'wards' WHEN 'save_bed' THEN 'beds' WHEN 'save_medicine_item' THEN 'medicine_items' WHEN 'receive_medicine_lot' THEN 'medicine_lots' WHEN 'save_payer_accreditation' THEN 'payer_accreditations' WHEN 'save_asset' THEN 'assets' WHEN 'save_privacy_incident' THEN 'privacy_incidents' WHEN 'save_data_request' THEN 'data_requests' WHEN 'log_disclosure' THEN 'disclosures' WHEN 'save_external_workflow' THEN 'external_workflows' WHEN 'link_evidence' THEN 'evidence' WHEN 'create_replenishment_request' THEN 'replenishment_requests' WHEN 'save_invoice' THEN 'invoices' WHEN 'create_claim' THEN 'claims' WHEN 'save_follow_up' THEN 'follow_ups' WHEN 'create_appointment' THEN 'appointments' WHEN 'create_encounter' THEN 'encounters' WHEN 'assign_queue_entry' THEN 'queue_entries' WHEN 'record_triage' THEN 'triage_events' WHEN 'save_clinical_record' THEN 'clinical_records' WHEN 'create_diagnostic_order' THEN 'diagnostic_orders' WHEN 'create_specimen' THEN 'specimens' WHEN 'record_diagnostic_result' THEN 'diagnostic_results' WHEN 'create_medication_order' THEN 'medication_orders' WHEN 'record_medication_administration' THEN 'medication_administrations' WHEN 'admit_patient' THEN 'admissions' WHEN 'save_procedure' THEN 'procedures' WHEN 'save_discharge' THEN 'discharges' ELSE 'external_workflows' END;
  IF NOT (p_payload ? 'id') OR NULLIF(p_payload->>'id','') IS NULL THEN IF (p_payload->>'expected_version')::bigint<>0 THEN RAISE EXCEPTION 'Create expected_version must be zero' USING ERRCODE='40001'; END IF; ELSE EXECUTE format('SELECT version FROM public.office_health_admin_%I WHERE id=$1 AND workspace_id=$2',tab) INTO current_version USING (p_payload->>'id')::uuid,p_workspace_id; IF current_version IS NULL OR current_version<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale or outside-workspace entity version' USING ERRCODE='40001'; END IF; END IF; eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid()); EXECUTE format('INSERT INTO public.office_health_admin_%I(id,workspace_id,facility_id,department_id,patient_id,encounter_id,order_id,invoice_id,admission_id,bed_id,item_id,lot_id,asset_id,display_label,status,kind,official_reference,source_url,amount_tzs,quantity,nonce,ciphertext,metadata,created_by) VALUES($1,$2,NULLIF($3,'''')::uuid,NULLIF($4,'''')::uuid,NULLIF($5,'''')::uuid,NULLIF($6,'''')::uuid,NULLIF($7,'''')::uuid,NULLIF($8,'''')::uuid,NULLIF($9,'''')::uuid,NULLIF($10,'''')::uuid,NULLIF($11,'''')::uuid,NULLIF($12,'''')::uuid,NULLIF($13,'''')::uuid,$14,coalesce(NULLIF($15,''''),''draft''),$16,$17,$18,NULLIF($19,'''')::numeric,NULLIF($20,'''')::numeric,decode(NULLIF($21,''''),''base64''),decode(NULLIF($22,''''),''base64''),$23,$24) ON CONFLICT(id) DO UPDATE SET status=excluded.status,nonce=excluded.nonce,ciphertext=excluded.ciphertext,metadata=excluded.metadata,version=public.office_health_admin_%I.version+1,updated_at=now() WHERE public.office_health_admin_%I.workspace_id=$2 AND public.office_health_admin_%I.version=coalesce(NULLIF($25,'''')::bigint,0) RETURNING jsonb_build_object(''id'',id,''version'',version,''status'',status)',tab,tab,tab,tab) INTO result USING eid,p_workspace_id,p_payload->>'facility_id',p_payload->>'department_id',p_payload->>'patient_id',p_payload->>'encounter_id',p_payload->>'order_id',p_payload->>'invoice_id',p_payload->>'admission_id',p_payload->>'bed_id',p_payload->>'item_id',p_payload->>'lot_id',p_payload->>'asset_id',office_private.health_action_display_label(p_action,p_payload),coalesce(p_payload->>'state',p_payload->>'status'),'record',p_payload->>'official_reference',p_payload->>'source_url',p_payload->>'amount_tzs',coalesce(p_payload->>'quantity',p_payload->>'requested_quantity'),p_payload->>'nonce',p_payload->>'ciphertext',office_private.health_action_metadata(p_action,p_payload),auth.uid(),p_payload->>'expected_version',p_payload->>'expected_version';
 ELSIF p_action IN('register_patient','update_patient_private') THEN PERFORM office_private.health_authorize(p_workspace_id,'patient_registration',true); IF p_action='register_patient' AND p_payload ? 'id' AND EXISTS(SELECT 1 FROM public.office_health_admin_patients WHERE id=(p_payload->>'id')::uuid) THEN RAISE EXCEPTION 'register_patient is create-only' USING ERRCODE='23505'; END IF; IF p_payload->>'nonce' IS NULL OR p_payload->>'ciphertext' IS NULL THEN RAISE EXCEPTION 'Encrypted patient payload required' USING ERRCODE='22023'; END IF; eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid()); INSERT INTO public.office_health_admin_patients(id,workspace_id,facility_id,status,kind,nonce,ciphertext,metadata,created_by) VALUES(eid,p_workspace_id,NULLIF(p_payload->>'facility_id','')::uuid,'registered','patient',decode(p_payload->>'nonce','base64'),decode(p_payload->>'ciphertext','base64'),jsonb_build_object('action',p_action),auth.uid()) ON CONFLICT(id) DO UPDATE SET nonce=excluded.nonce,ciphertext=excluded.ciphertext,version=office_health_admin_patients.version+1,updated_at=now() WHERE office_health_admin_patients.workspace_id=p_workspace_id AND office_health_admin_patients.version=(p_payload->>'expected_version')::bigint RETURNING jsonb_build_object('id',id,'version',version,'status',status) INTO result; IF jsonb_typeof(p_payload->'blind_indexes')='array' THEN INSERT INTO public.office_health_admin_patient_blind_indexes(workspace_id,patient_id,index_type,digest) SELECT p_workspace_id,eid,x->>'index_type',decode(x->>'digest','base64') FROM jsonb_array_elements(p_payload->'blind_indexes') x ON CONFLICT DO NOTHING; END IF;
 ELSIF p_action='audit_sensitive_export' THEN
  PERFORM office_private.health_authorize(p_workspace_id,'export',true);
  IF p_payload->>'purpose_code' <> 'authorized_export' OR jsonb_typeof(p_payload->'entity_ids')<>'array' OR jsonb_array_length(p_payload->'entity_ids')<1 OR jsonb_array_length(p_payload->'entity_ids')>1000 THEN RAISE EXCEPTION 'Authorized export requires selected entities and purpose' USING ERRCODE='22023'; END IF;
  IF p_payload->>'resource' NOT IN ('audit','facility_report','clinical_report','diagnostic_report','pharmacy_report','inpatient_report','billing_report','claims_report','compliance_report','staff_report') THEN RAISE EXCEPTION 'Unknown export report resource' USING ERRCODE='22023'; END IF;
  export_tab:=CASE p_payload->>'resource' WHEN 'audit' THEN 'audit_log' WHEN 'facility_report' THEN 'facilities' WHEN 'clinical_report' THEN 'clinical_records' WHEN 'diagnostic_report' THEN 'diagnostic_results' WHEN 'pharmacy_report' THEN 'medication_orders' WHEN 'inpatient_report' THEN 'admissions' WHEN 'billing_report' THEN 'invoices' WHEN 'claims_report' THEN 'claims' WHEN 'compliance_report' THEN 'privacy_incidents' WHEN 'staff_report' THEN 'staff_roles' END;
  FOR export_id IN SELECT jsonb_array_elements_text(p_payload->'entity_ids') LOOP
    IF export_id !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$' THEN RAISE EXCEPTION 'Export entity IDs must be UUIDs' USING ERRCODE='22023'; END IF;
    export_uuid:=export_id::uuid;
    IF p_payload->>'resource'='audit' THEN
      EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.office_health_admin_audit_log WHERE workspace_id=$1 AND entity_id=$2)' INTO export_exists USING p_workspace_id,export_uuid;
    ELSE
      EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.office_health_admin_%I WHERE workspace_id=$1 AND id=$2)',export_tab) INTO export_exists USING p_workspace_id,export_uuid;
    END IF;
    IF NOT export_exists THEN RAISE EXCEPTION 'Export entity is outside workspace or does not exist' USING ERRCODE='42501'; END IF;
  END LOOP;
  INSERT INTO public.office_health_admin_audit_log(workspace_id,actor_id,resource,action,entity_count,purpose_code) VALUES(p_workspace_id,auth.uid(),p_payload->>'resource','export',jsonb_array_length(p_payload->'entity_ids'),'authorized_export'); result:=jsonb_build_object('id',gen_random_uuid(),'version',1,'audited',true,'count',jsonb_array_length(p_payload->'entity_ids'));
 ELSIF p_action IN('transition_license','transition_staff_credential','review_duplicate_case','transition_appointment','reschedule_appointment','transition_encounter','transition_diagnostic_order','record_specimen_handoff','approve_diagnostic_result','deliver_diagnostic_result','transition_medication_order','assign_bed','transfer_patient','transition_procedure','finalize_discharge','record_payment','transition_claim','record_claim_response','record_stock_movement','quarantine_medicine_lot','dispose_medicine_lot','transition_replenishment_request','record_asset_maintenance','transition_privacy_incident','transition_data_request','supersede_evidence') THEN
  PERFORM office_private.health_authorize(p_workspace_id,office_private.health_action_capability(p_action),phi);
  tab:=CASE p_action WHEN 'transition_license' THEN 'licenses' WHEN 'transition_staff_credential' THEN 'staff_credentials' WHEN 'review_duplicate_case' THEN 'duplicate_cases' WHEN 'transition_appointment' THEN 'appointments' WHEN 'reschedule_appointment' THEN 'appointments' WHEN 'transition_encounter' THEN 'encounters' WHEN 'record_specimen_handoff' THEN 'specimens' WHEN 'transition_diagnostic_order' THEN 'diagnostic_orders' WHEN 'approve_diagnostic_result' THEN 'diagnostic_results' WHEN 'deliver_diagnostic_result' THEN 'diagnostic_results' WHEN 'transition_medication_order' THEN 'medication_orders' WHEN 'assign_bed' THEN 'bed_assignments' WHEN 'transfer_patient' THEN 'transfers' WHEN 'transition_procedure' THEN 'procedures' WHEN 'finalize_discharge' THEN 'discharges' WHEN 'record_payment' THEN 'payments' WHEN 'transition_claim' THEN 'claims' WHEN 'record_stock_movement' THEN 'stock_movements' WHEN 'quarantine_medicine_lot' THEN 'medicine_lots' WHEN 'dispose_medicine_lot' THEN 'medicine_lots' WHEN 'transition_replenishment_request' THEN 'replenishment_requests' WHEN 'record_asset_maintenance' THEN 'asset_maintenance' WHEN 'transition_privacy_incident' THEN 'privacy_incidents' WHEN 'transition_data_request' THEN 'data_requests' WHEN 'supersede_evidence' THEN 'evidence' ELSE 'evidence' END;
  EXECUTE format($sql$UPDATE public.office_health_admin_%I SET status=coalesce(NULLIF($1,''),status),version=version+1,updated_at=now() WHERE id=$2::uuid AND workspace_id=$3::uuid AND version=$4::bigint AND (facility_id IS NULL OR office_private.health_scope_ok($3::uuid,facility_id,department_id)) RETURNING jsonb_build_object('id',id,'version',version,'status',status)$sql$,tab) INTO result USING coalesce(NULLIF(p_payload->>'state',''),p_payload->>'status'),p_payload->>'id',p_workspace_id,p_payload->>'expected_version';
 ELSE RAISE EXCEPTION 'Action is not implemented' USING ERRCODE='0A000'; END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'Invalid entity, scope, or expected_version' USING ERRCODE='40001'; END IF;
 INSERT INTO public.office_health_admin_request_dedup(workspace_id,idempotency_key,actor_id,action,request_hash,response) VALUES(p_workspace_id,idem,auth.uid(),p_action,h,result); INSERT INTO public.office_health_admin_audit_log(workspace_id,actor_id,resource,action,entity_id) VALUES(p_workspace_id,auth.uid(),coalesce(tab,p_action),'write',NULLIF(result->>'id','')::uuid); RETURN result;
END$$;

-- Keep the broad dispatcher for legacy actions, but route the critical workflows
-- through explicit locked mutations below.  These branches intentionally avoid
-- the generic unscoped upsert/transition paths.
ALTER FUNCTION public.office_health_admin_command(uuid,text,jsonb) RENAME TO office_health_admin_command_generic;
CREATE OR REPLACE FUNCTION office_private.health_action_metadata(a text,p jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(jsonb_object_agg(key,value ORDER BY key),'{}'::jsonb)
 FROM jsonb_each(p)
 WHERE key NOT IN ('id','expected_version','idempotency_key','key_config','nonce','ciphertext','blind_indexes','claim_id');
$$;
CREATE OR REPLACE FUNCTION office_private.health_action_display_label(a text,p jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(nullif(p->>'display_name',''),nullif(p->>'name',''),nullif(p->>'label',''),nullif(p->>'code',''),nullif(p->>'facility_code',''),nullif(p->>'license_kind',''),nullif(p->>'asset_type',''),a);
$$;
CREATE OR REPLACE FUNCTION public.office_health_admin_command(p_workspace_id uuid,p_action text,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
  role text; idem uuid; h text; prior_hash text; old text; result jsonb;
  expected bigint; eid uuid; f uuid; d uuid; ward_f uuid; ward_d uuid;
  adm_f uuid; adm_d uuid; adm_status text; adm_bed uuid; bed_f uuid; bed_d uuid; bed_status text;
  from_f uuid; from_d uuid; from_status text; to_f uuid; to_d uuid; to_status text;
  inv_f uuid; inv_d uuid; inv_amount numeric; paid numeric; claimed numeric; req numeric; balance numeric;
  existing_version bigint; scope_user uuid; dept uuid; member_status text; facility_code text;
BEGIN
  IF p_action NOT IN ('save_facility','transition_facility','configure_private_key','assign_staff_role','save_bed','assign_bed','transfer_patient','record_payment','create_claim','assign_facility_scope') THEN
    RETURN public.office_health_admin_command_generic(p_workspace_id,p_action,p_payload);
  END IF;
  IF jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'Invalid payload' USING ERRCODE='22023'; END IF;
  PERFORM office_private.health_validate_payload(p_action,p_payload);
  idem:=NULLIF(p_payload->>'idempotency_key','')::uuid;
  IF idem IS NULL THEN RAISE EXCEPTION 'idempotency_key required' USING ERRCODE='22023'; END IF;
  h:=encode(sha256(convert_to(p_action||':'||p_payload::text,'UTF8')),'hex');
  SELECT request_hash,response::text INTO prior_hash,old FROM public.office_health_admin_request_dedup
    WHERE workspace_id=p_workspace_id AND idempotency_key=idem FOR UPDATE;
  IF old IS NOT NULL THEN IF h<>prior_hash THEN RAISE EXCEPTION 'Idempotency key payload mismatch' USING ERRCODE='23505'; END IF; RETURN old::jsonb; END IF;
  role:=office_private.health_context(p_workspace_id);
  PERFORM office_private.health_authorize(p_workspace_id,office_private.health_action_capability(p_action),office_private.health_action_requires_gate(p_action));
  IF p_action='assign_facility_scope' AND role<>'health_admin' THEN RAISE EXCEPTION 'Health admin required' USING ERRCODE='42501'; END IF;

  IF p_action='configure_private_key' THEN
    IF role<>'health_admin' THEN RAISE EXCEPTION 'Health Administration owner capability required' USING ERRCODE='42501'; END IF;
    SELECT version INTO existing_version FROM public.office_health_admin_settings WHERE workspace_id=p_workspace_id FOR UPDATE;
    IF existing_version IS NULL THEN RAISE EXCEPTION 'Health settings bootstrap missing' USING ERRCODE='55000'; END IF;
    IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale settings version' USING ERRCODE='40001'; END IF;
    UPDATE public.office_health_admin_settings SET key_config=p_payload->'key_config',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id RETURNING jsonb_build_object('id',workspace_id,'version',version,'configured',true) INTO result;
  ELSIF p_action='assign_staff_role' THEN
    SELECT status INTO member_status FROM public.office_memberships WHERE workspace_id=p_workspace_id AND user_id=(p_payload->>'user_id')::uuid FOR UPDATE;
    IF member_status IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'Target must be an active workspace member' USING ERRCODE='42501'; END IF;
    SELECT version INTO existing_version FROM public.office_health_admin_staff_roles WHERE workspace_id=p_workspace_id AND user_id=(p_payload->>'user_id')::uuid FOR UPDATE;
    IF existing_version IS NULL THEN IF (p_payload->>'expected_version')::bigint<>0 THEN RAISE EXCEPTION 'Invalid staff role version' USING ERRCODE='40001'; END IF; INSERT INTO public.office_health_admin_staff_roles(workspace_id,user_id,health_role) VALUES(p_workspace_id,(p_payload->>'user_id')::uuid,p_payload->>'role') RETURNING jsonb_build_object('id',user_id,'version',version,'role',health_role) INTO result;
    ELSE IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale staff role version' USING ERRCODE='40001'; END IF; UPDATE public.office_health_admin_staff_roles SET health_role=p_payload->>'role',active=true,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND user_id=(p_payload->>'user_id')::uuid RETURNING jsonb_build_object('id',user_id,'version',version,'role',health_role) INTO result; END IF;
  ELSIF p_action IN ('save_facility','transition_facility') THEN
    PERFORM office_private.health_authorize(p_workspace_id,'facility_admin');
    IF p_action='transition_facility' THEN SELECT workspace_id,version INTO scope_user,existing_version FROM public.office_health_admin_facilities WHERE id=(p_payload->>'id')::uuid FOR UPDATE; f:=(p_payload->>'id')::uuid; IF scope_user IS DISTINCT FROM p_workspace_id THEN RAISE EXCEPTION 'Facility is outside workspace' USING ERRCODE='40001'; END IF; IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale facility version' USING ERRCODE='40001'; END IF; IF NOT office_private.health_scope_ok(p_workspace_id,f,NULL) THEN RAISE EXCEPTION 'Active facility scope required' USING ERRCODE='42501'; END IF; UPDATE public.office_health_admin_facilities SET status=p_payload->>'state',version=version+1,updated_at=now() WHERE id=(p_payload->>'id')::uuid RETURNING jsonb_build_object('id',id,'version',version,'status',status) INTO result;
    ELSE eid:=NULLIF(p_payload->>'id','')::uuid; IF eid IS NULL THEN IF role<>'health_admin' THEN RAISE EXCEPTION 'Only health_admin may create facilities' USING ERRCODE='42501'; END IF; IF (p_payload->>'expected_version')::bigint<>0 THEN RAISE EXCEPTION 'Create expected_version must be zero' USING ERRCODE='40001'; END IF; eid:=gen_random_uuid(); INSERT INTO public.office_health_admin_facilities(id,workspace_id,facility_code,display_name,facility_type,district,region,ownership,status,official_reference,source_url,created_by) VALUES(eid,p_workspace_id,p_payload->>'facility_code',p_payload->>'display_name',p_payload->>'facility_type',p_payload->>'district',p_payload->>'region',p_payload->>'ownership',coalesce(p_payload->>'state','draft'),p_payload->>'official_reference',p_payload->>'source_url',auth.uid()) RETURNING jsonb_build_object('id',id,'version',version,'status',status) INTO result; ELSE SELECT workspace_id,version INTO scope_user,existing_version FROM public.office_health_admin_facilities WHERE id=eid FOR UPDATE; f:=eid; IF scope_user IS DISTINCT FROM p_workspace_id THEN RAISE EXCEPTION 'Facility is outside workspace' USING ERRCODE='42501'; END IF; IF NOT office_private.health_scope_ok(p_workspace_id,eid,NULL) THEN RAISE EXCEPTION 'Active facility scope required' USING ERRCODE='42501'; END IF; IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale facility version' USING ERRCODE='40001'; END IF; UPDATE public.office_health_admin_facilities SET facility_code=coalesce(p_payload->>'facility_code',public.office_health_admin_facilities.facility_code),display_name=p_payload->>'display_name',facility_type=p_payload->>'facility_type',district=p_payload->>'district',region=p_payload->>'region',ownership=p_payload->>'ownership',status=coalesce(p_payload->>'state',public.office_health_admin_facilities.status),official_reference=p_payload->>'official_reference',source_url=p_payload->>'source_url',version=public.office_health_admin_facilities.version+1,updated_at=now() WHERE id=eid RETURNING jsonb_build_object('id',id,'version',version,'status',status) INTO result; END IF; END IF;
  ELSIF p_action='save_bed' THEN
    SELECT facility_id,department_id INTO ward_f,ward_d FROM public.office_health_admin_wards
      WHERE id=(p_payload->>'ward_id')::uuid AND workspace_id=p_workspace_id AND status NOT IN ('inactive','archived') FOR UPDATE;
    IF ward_f IS NULL THEN RAISE EXCEPTION 'Ward is outside workspace' USING ERRCODE='42501'; END IF;
    IF p_payload ? 'facility_id' AND NULLIF(p_payload->>'facility_id','')::uuid IS DISTINCT FROM ward_f THEN RAISE EXCEPTION 'Ward facility mismatch' USING ERRCODE='42501'; END IF;
    IF p_payload ? 'department_id' AND NULLIF(p_payload->>'department_id','')::uuid IS DISTINCT FROM ward_d THEN RAISE EXCEPTION 'Ward department mismatch' USING ERRCODE='42501'; END IF;
    IF NOT office_private.health_scope_ok(p_workspace_id,ward_f,ward_d) THEN RAISE EXCEPTION 'Active facility and department scope required' USING ERRCODE='42501'; END IF;
    IF NOT (p_payload ? 'id') OR NULLIF(p_payload->>'id','') IS NULL THEN IF (p_payload->>'expected_version')::bigint<>0 THEN RAISE EXCEPTION 'Create expected_version must be zero' USING ERRCODE='40001'; END IF; ELSE SELECT version INTO existing_version FROM public.office_health_admin_beds WHERE id=(p_payload->>'id')::uuid AND workspace_id=p_workspace_id FOR UPDATE; IF existing_version IS NULL OR existing_version<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale or outside-workspace bed version' USING ERRCODE='40001'; END IF; END IF;
    eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid());
    IF p_payload->>'state' IS NOT NULL AND p_payload->>'state' NOT IN ('draft','available','occupied','maintenance','inactive') THEN RAISE EXCEPTION 'Invalid bed state' USING ERRCODE='22023'; END IF;
    INSERT INTO public.office_health_admin_beds(id,workspace_id,facility_id,department_id,status,kind,display_label,created_by)
      VALUES(eid,p_workspace_id,ward_f,ward_d,coalesce(p_payload->>'state','available'),'bed',p_payload->>'label',auth.uid())
      ON CONFLICT(id) DO UPDATE SET display_label=excluded.display_label,status=excluded.status,facility_id=ward_f,department_id=ward_d,version=office_health_admin_beds.version+1,updated_at=now()
      WHERE office_health_admin_beds.workspace_id=p_workspace_id AND office_health_admin_beds.version=(p_payload->>'expected_version')::bigint
      AND office_health_admin_beds.status IN ('draft','available','maintenance') AND excluded.status IN ('draft','available','maintenance')
      RETURNING jsonb_build_object('id',id,'version',version,'status',status,'facility_id',facility_id,'department_id',department_id) INTO result;
  ELSIF p_action='assign_bed' THEN
    SELECT facility_id,department_id,status,bed_id INTO adm_f,adm_d,adm_status,adm_bed FROM public.office_health_admin_admissions
      WHERE id=(p_payload->>'admission_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
    SELECT facility_id,department_id,status INTO bed_f,bed_d,bed_status FROM public.office_health_admin_beds
      WHERE id=(p_payload->>'bed_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
    IF adm_f IS NULL OR bed_f IS NULL THEN RAISE EXCEPTION 'Admission or bed is outside workspace' USING ERRCODE='42501'; END IF;
    IF adm_status NOT IN ('active','admitted') OR bed_status NOT IN ('available','draft') OR bed_f<>adm_f OR bed_d IS DISTINCT FROM adm_d OR NOT office_private.health_scope_ok(p_workspace_id,adm_f,adm_d) THEN RAISE EXCEPTION 'Admission and bed are not assignable in scope' USING ERRCODE='42501'; END IF;
    IF (p_payload->>'expected_version')::bigint IS DISTINCT FROM (SELECT version FROM public.office_health_admin_admissions WHERE id=(p_payload->>'admission_id')::uuid) THEN RAISE EXCEPTION 'Stale admission version' USING ERRCODE='40001'; END IF;
    IF adm_bed IS NOT NULL THEN RAISE EXCEPTION 'Admission already has a bed' USING ERRCODE='40001'; END IF;
    eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid());
    INSERT INTO public.office_health_admin_bed_assignments(id,workspace_id,facility_id,department_id,admission_id,bed_id,status,kind,created_by)
      VALUES(eid,p_workspace_id,adm_f,adm_d,(p_payload->>'admission_id')::uuid,(p_payload->>'bed_id')::uuid,'assigned','bed_assignment',auth.uid());
    UPDATE public.office_health_admin_beds SET status='occupied',version=version+1,updated_at=now() WHERE id=(p_payload->>'bed_id')::uuid;
    UPDATE public.office_health_admin_admissions SET bed_id=(p_payload->>'bed_id')::uuid,status='admitted',version=version+1,updated_at=now() WHERE id=(p_payload->>'admission_id')::uuid;
    result:=jsonb_build_object('id',eid,'version',1,'status','assigned','bed_id',(p_payload->>'bed_id')::uuid,'admission_id',(p_payload->>'admission_id')::uuid);
  ELSIF p_action='transfer_patient' THEN
    SELECT facility_id,department_id,status,bed_id,version INTO adm_f,adm_d,adm_status,adm_bed,existing_version FROM public.office_health_admin_admissions WHERE id=(p_payload->>'admission_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
    SELECT facility_id,department_id,status INTO from_f,from_d,from_status FROM public.office_health_admin_beds WHERE id=(p_payload->>'from_bed_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
    SELECT facility_id,department_id,status INTO to_f,to_d,to_status FROM public.office_health_admin_beds WHERE id=(p_payload->>'to_bed_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
    IF adm_f IS NULL OR from_f IS NULL OR to_f IS NULL THEN RAISE EXCEPTION 'Transfer rows are outside workspace' USING ERRCODE='42501'; END IF;
    IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale admission version' USING ERRCODE='40001'; END IF;
    IF adm_status NOT IN ('active','admitted') OR adm_bed<>(p_payload->>'from_bed_id')::uuid OR from_status<>'occupied' OR to_status NOT IN ('available','draft') OR from_f<>adm_f OR to_f<>adm_f OR from_d IS DISTINCT FROM adm_d OR to_d IS DISTINCT FROM adm_d OR NOT office_private.health_scope_ok(p_workspace_id,adm_f,adm_d) THEN RAISE EXCEPTION 'Invalid current assignment or destination bed' USING ERRCODE='40001'; END IF;
    UPDATE public.office_health_admin_bed_assignments SET status='transferred',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND admission_id=(p_payload->>'admission_id')::uuid AND bed_id=(p_payload->>'from_bed_id')::uuid AND status='assigned';
    IF NOT FOUND THEN RAISE EXCEPTION 'Current bed assignment not found' USING ERRCODE='40001'; END IF;
    UPDATE public.office_health_admin_beds SET status='available',version=version+1,updated_at=now() WHERE id=(p_payload->>'from_bed_id')::uuid;
    UPDATE public.office_health_admin_beds SET status='occupied',version=version+1,updated_at=now() WHERE id=(p_payload->>'to_bed_id')::uuid;
    eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid());
    INSERT INTO public.office_health_admin_bed_assignments(id,workspace_id,facility_id,department_id,admission_id,bed_id,status,kind,created_by) VALUES(eid,p_workspace_id,adm_f,adm_d,(p_payload->>'admission_id')::uuid,(p_payload->>'to_bed_id')::uuid,'assigned','bed_assignment',auth.uid());
    INSERT INTO public.office_health_admin_transfers(id,workspace_id,facility_id,department_id,admission_id,bed_id,status,kind,display_label,created_by) VALUES(coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid()),p_workspace_id,adm_f,adm_d,(p_payload->>'admission_id')::uuid,(p_payload->>'to_bed_id')::uuid,'completed','transfer',p_payload->>'reason',auth.uid());
    UPDATE public.office_health_admin_admissions SET bed_id=(p_payload->>'to_bed_id')::uuid,version=version+1,updated_at=now() WHERE id=(p_payload->>'admission_id')::uuid;
    result:=jsonb_build_object('id',eid,'version',existing_version+1,'status','completed','bed_id',(p_payload->>'to_bed_id')::uuid);
  ELSIF p_action='record_payment' THEN
    SELECT facility_id,department_id,amount_tzs,version INTO inv_f,inv_d,inv_amount,existing_version FROM public.office_health_admin_invoices WHERE id=(p_payload->>'invoice_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
    IF inv_f IS NULL OR NOT office_private.health_scope_ok(p_workspace_id,inv_f,inv_d) THEN RAISE EXCEPTION 'Invoice is outside workspace/scope' USING ERRCODE='42501'; END IF;
    IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale invoice version' USING ERRCODE='40001'; END IF;
    req:=(p_payload->>'amount_tzs')::numeric; IF req<0 OR scale(req)>2 THEN RAISE EXCEPTION 'Invalid payment amount' USING ERRCODE='22023'; END IF;
    SELECT coalesce(sum(amount_tzs),0) INTO paid FROM public.office_health_admin_payments WHERE workspace_id=p_workspace_id AND invoice_id=(p_payload->>'invoice_id')::uuid AND status NOT IN ('void','cancelled'); balance:=inv_amount-paid; IF req>balance THEN RAISE EXCEPTION 'Payment exceeds outstanding balance' USING ERRCODE='22023'; END IF;
    eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid()); INSERT INTO public.office_health_admin_payments(id,workspace_id,facility_id,department_id,invoice_id,status,kind,amount_tzs,official_reference,created_by) VALUES(eid,p_workspace_id,inv_f,inv_d,(p_payload->>'invoice_id')::uuid,coalesce(p_payload->>'state','posted'),'payment',req,p_payload->>'reference',auth.uid()); UPDATE public.office_health_admin_invoices SET status=CASE WHEN req=balance THEN 'paid' ELSE 'partially_paid' END,version=version+1,updated_at=now() WHERE id=(p_payload->>'invoice_id')::uuid; result:=jsonb_build_object('id',eid,'version',1,'status',CASE WHEN req=balance THEN 'paid' ELSE 'partially_paid' END,'balance',balance-req);
  ELSIF p_action='create_claim' THEN
    SELECT facility_id,department_id,amount_tzs,version INTO inv_f,inv_d,inv_amount,existing_version FROM public.office_health_admin_invoices WHERE id=(p_payload->>'invoice_id')::uuid AND workspace_id=p_workspace_id FOR UPDATE;
    IF inv_f IS NULL OR NOT office_private.health_scope_ok(p_workspace_id,inv_f,inv_d) THEN RAISE EXCEPTION 'Invoice is outside workspace/scope' USING ERRCODE='42501'; END IF;
    IF (p_payload->>'nonce') IS NULL OR (p_payload->>'ciphertext') IS NULL THEN RAISE EXCEPTION 'Encrypted claim payload required' USING ERRCODE='22023'; END IF;
    IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale invoice version' USING ERRCODE='40001'; END IF;
    req:=(p_payload->>'amount_tzs')::numeric; SELECT coalesce(sum(amount_tzs),0) INTO paid FROM public.office_health_admin_payments WHERE workspace_id=p_workspace_id AND invoice_id=(p_payload->>'invoice_id')::uuid AND status NOT IN ('void','cancelled'); SELECT coalesce(sum(amount_tzs),0) INTO claimed FROM public.office_health_admin_claims WHERE workspace_id=p_workspace_id AND invoice_id=(p_payload->>'invoice_id')::uuid AND status NOT IN ('rejected','cancelled'); balance:=inv_amount-paid-claimed; IF req<0 OR req>balance THEN RAISE EXCEPTION 'Claim exceeds eligible balance' USING ERRCODE='22023'; END IF;
    eid:=coalesce(NULLIF(p_payload->>'id','')::uuid,gen_random_uuid()); INSERT INTO public.office_health_admin_claims(id,workspace_id,facility_id,department_id,invoice_id,status,kind,amount_tzs,nonce,ciphertext,created_by) VALUES(eid,p_workspace_id,inv_f,inv_d,(p_payload->>'invoice_id')::uuid,coalesce(p_payload->>'state','submitted'),'claim',req,decode(p_payload->>'nonce','base64'),decode(p_payload->>'ciphertext','base64'),auth.uid()); UPDATE public.office_health_admin_invoices SET version=version+1,updated_at=now() WHERE id=(p_payload->>'invoice_id')::uuid; result:=jsonb_build_object('id',eid,'version',1,'status',coalesce(p_payload->>'state','submitted'),'eligible_balance',balance-req);
  ELSE
    scope_user:=(p_payload->>'staff_role_id')::uuid; dept:=NULLIF(p_payload->>'department_id','')::uuid;
    IF NOT EXISTS(SELECT 1 FROM public.office_memberships WHERE workspace_id=p_workspace_id AND user_id=scope_user AND status='active') OR NOT EXISTS(SELECT 1 FROM public.office_health_admin_staff_roles WHERE workspace_id=p_workspace_id AND user_id=scope_user AND active) THEN RAISE EXCEPTION 'Target must be active workspace staff with active health role' USING ERRCODE='42501'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.office_health_admin_facilities WHERE id=(p_payload->>'facility_id')::uuid AND workspace_id=p_workspace_id AND status NOT IN ('inactive','archived')) OR (dept IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_health_admin_departments WHERE id=dept AND workspace_id=p_workspace_id AND facility_id=(p_payload->>'facility_id')::uuid AND status NOT IN ('inactive','archived'))) THEN RAISE EXCEPTION 'Facility or department is outside workspace' USING ERRCODE='42501'; END IF;
    SELECT version INTO existing_version FROM public.office_health_admin_staff_facility_scopes WHERE workspace_id=p_workspace_id AND user_id=scope_user AND facility_id=(p_payload->>'facility_id')::uuid AND department_id IS NOT DISTINCT FROM dept FOR UPDATE;
    IF existing_version IS NULL THEN IF (p_payload->>'expected_version')::bigint<>0 THEN RAISE EXCEPTION 'Invalid scope version' USING ERRCODE='40001'; END IF; INSERT INTO public.office_health_admin_staff_facility_scopes(workspace_id,user_id,facility_id,department_id) VALUES(p_workspace_id,scope_user,(p_payload->>'facility_id')::uuid,dept) RETURNING jsonb_build_object('id',user_id,'version',version,'active',active) INTO result;
    ELSE IF (p_payload->>'expected_version')::bigint<>existing_version THEN RAISE EXCEPTION 'Stale scope version' USING ERRCODE='40001'; END IF; UPDATE public.office_health_admin_staff_facility_scopes SET active=true,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND user_id=scope_user AND facility_id=(p_payload->>'facility_id')::uuid AND department_id IS NOT DISTINCT FROM dept RETURNING jsonb_build_object('id',user_id,'version',version,'active',active) INTO result; END IF;
  END IF;
  IF result IS NULL THEN RAISE EXCEPTION 'Invalid entity, scope, or expected version' USING ERRCODE='40001'; END IF;
  INSERT INTO public.office_health_admin_request_dedup(workspace_id,idempotency_key,actor_id,action,request_hash,response) VALUES(p_workspace_id,idem,auth.uid(),p_action,h,result);
  INSERT INTO public.office_health_admin_audit_log(workspace_id,actor_id,facility_id,department_id,resource,action,entity_id) VALUES(p_workspace_id,auth.uid(),coalesce(inv_f,adm_f,ward_f),coalesce(inv_d,adm_d,ward_d),p_action,'write',NULLIF(result->>'id','')::uuid);
  RETURN result;
END$$;

CREATE OR REPLACE FUNCTION office_private.health_admin_settings_on_industry_space() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NEW.industry_id='healthcare-admin' THEN
  INSERT INTO public.office_health_admin_settings(workspace_id) VALUES(NEW.workspace_id) ON CONFLICT (workspace_id) DO NOTHING;
 END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER office_health_admin_settings_on_industry_space
 AFTER INSERT ON public.office_industry_spaces
 FOR EACH ROW EXECUTE FUNCTION office_private.health_admin_settings_on_industry_space();

INSERT INTO public.office_health_admin_settings(workspace_id)
SELECT workspace_id FROM public.office_industry_spaces WHERE industry_id='healthcare-admin'
ON CONFLICT (workspace_id) DO NOTHING;

DO $$ DECLARE n text; BEGIN FOR n IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'office_health_admin_%' LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',n); EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated',n); EXECUTE format('CREATE POLICY %I_no_direct_access ON public.%I FOR ALL TO authenticated USING(false) WITH CHECK(false)',n,n); END LOOP; END $$;
DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='office_private' AND p.proname LIKE 'health_%' LOOP EXECUTE 'REVOKE ALL ON FUNCTION '||f.sig||' FROM PUBLIC,anon,authenticated'; END LOOP; END $$;
REVOKE ALL ON FUNCTION office_private.health_admin_settings_on_industry_space() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.office_health_admin_command_generic(uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.office_health_admin_read(uuid,text,jsonb,int,int,text),public.office_health_admin_command(uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.office_health_admin_read(uuid,text,jsonb,int,int,text),public.office_health_admin_command(uuid,text,jsonb) TO authenticated;
COMMIT;
